/**
 * Manually maintained — not generated by Orval.
 * Provides hooks for the gym-owner tenant endpoints (/tenants/me).
 */
import {
  useQuery,
} from '@tanstack/react-query';
import type {
  DataTag,
  QueryClient,
  QueryFunction,
  QueryKey,
  UndefinedInitialDataOptions,
  UseQueryOptions,
  UseQueryResult,
} from '@tanstack/react-query';

import type { Tenant } from '../schemas/tenant';
import type { Plan } from '../schemas/plan';
import { orvalMutator } from '../../../lib/orval-mutator';
import type { ErrorType } from '../../../lib/orval-mutator';

// ─── Response shape ───────────────────────────────────────────────────────────

export interface GetMyTenantResponse {
  success: boolean;
  data: Tenant & {
    owner?: {
      firstName: string;
      lastName:  string;
      email:     string;
      lastLoginAt?: string;
      status: string;
    };
  };
}

// ─── Fetcher ──────────────────────────────────────────────────────────────────

export const getMyTenant = (signal?: AbortSignal) =>
  orvalMutator<GetMyTenantResponse>({ url: '/tenants/me', method: 'GET', signal });

// ─── Query key ────────────────────────────────────────────────────────────────

export const getGetMyTenantQueryKey = () => ['/tenants/me'] as const;

export const getGetMyTenantQueryOptions = <
  TData = Awaited<ReturnType<typeof getMyTenant>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof getMyTenant>>, TError, TData>>;
}) => {
  const { query: queryOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetMyTenantQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getMyTenant>>> = ({ signal }) =>
    getMyTenant(signal);

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getMyTenant>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

// ─── Hook ─────────────────────────────────────────────────────────────────────

/**
 * Returns the authenticated gym owner's own tenant record.
 * Includes plan name, quotas, feature flags, and settings.
 */
// ─── Plans list (accessible to any authenticated user) ────────────────────────

export interface GetTenantPlansResponse {
  success: boolean;
  data: Plan[];
}

export const getTenantPlans = (signal?: AbortSignal) =>
  orvalMutator<GetTenantPlansResponse>({ url: '/tenants/plans', method: 'GET', signal });

export const getGetTenantPlansQueryKey = () => ['/tenants/plans'] as const;

export const getGetTenantPlansQueryOptions = <
  TData = Awaited<ReturnType<typeof getTenantPlans>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof getTenantPlans>>, TError, TData>>;
}) => {
  const { query: queryOptions } = options ?? {};
  const queryKey = queryOptions?.queryKey ?? getGetTenantPlansQueryKey();
  const queryFn: QueryFunction<Awaited<ReturnType<typeof getTenantPlans>>> = ({ signal }) =>
    getTenantPlans(signal);
  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getTenantPlans>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

export function useGetTenantPlans<
  TData = Awaited<ReturnType<typeof getTenantPlans>>,
  TError = ErrorType<unknown>,
>(
  options?: { query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof getTenantPlans>>, TError, TData>> },
  queryClient?: QueryClient,
): UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {
  const queryOptions = getGetTenantPlansQueryOptions(options);
  const query = useQuery(queryOptions, queryClient) as UseQueryResult<TData, TError> & {
    queryKey: DataTag<QueryKey, TData, TError>;
  };
  return { ...query, queryKey: queryOptions.queryKey };
}

// ─── My Tenant hook ───────────────────────────────────────────────────────────

export function useGetMyTenant<
  TData = Awaited<ReturnType<typeof getMyTenant>>,
  TError = ErrorType<unknown>,
>(
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof getMyTenant>>, TError, TData>> &
      Pick<UndefinedInitialDataOptions<Awaited<ReturnType<typeof getMyTenant>>, TError, TData>, never>;
  },
  queryClient?: QueryClient,
): UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {
  const queryOptions = getGetMyTenantQueryOptions(options);
  const query = useQuery(queryOptions, queryClient) as UseQueryResult<TData, TError> & {
    queryKey: DataTag<QueryKey, TData, TError>;
  };
  return { ...query, queryKey: queryOptions.queryKey };
}
